package entities;public class Company extends Taxpayers {    private int quantityEmployee;    public Company() {    }    public Company(String name, Double annualIncome, int quantityEmployee) {        super(name, annualIncome);        this.quantityEmployee = quantityEmployee;    }    public int getQuantityEmployee() {        return quantityEmployee;    }    public void setQuantityEmployee(int quantityEmployee) {        this.quantityEmployee = quantityEmployee;    }    @Override    public Double taxPaid() {        double tax;        if(quantityEmployee > 10) {            tax = (getAnnualIncome() * 0.14);        }        else {            tax = (getAnnualIncome() * 0.16);        }        return tax;    }}